<?php require_once 'config/config.php'; require_room();$rid=room_id();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(room_role()!=='manager')exit('Manager access required.');$uid=(int)$_POST['user_id'];$amount=(float)$_POST['amount'];$date=$_POST['date']??date('Y-m-d');$method=trim($_POST['method']??'Cash');if($amount<=0){$error='Invalid amount.';}else{db()->prepare("INSERT INTO payments(room_id,user_id,amount,payment_date,method,recorded_by) VALUES(?,?,?,?,?,?)")->execute([$rid,$uid,$amount,$date,$method,user()['id']]);flash('Payment recorded.');redirect('payments.php');}}
$month=date('Y-m');$memberSql="SELECT rm.user_id,u.name FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=? AND rm.status='active'";$q=db()->prepare($memberSql);$q->execute([$rid]);$baseMembers=$q->fetchAll();$members=[];$days=(int)date('j');$sessions=(int)db()->query("SELECT meal_times FROM rooms WHERE id=".(int)$rid)->fetchColumn();
foreach($baseMembers as $bm){$q=db()->prepare("SELECT COUNT(*) FROM meals WHERE room_id=? AND user_id=? AND meal_date BETWEEN ? AND ? AND status='off'");$q->execute([$rid,$bm['user_id'],date('Y-m-01'),date('Y-m-d')]);$off=(int)$q->fetchColumn();$q=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE room_id=? AND user_id=? AND payment_date BETWEEN ? AND ?");$q->execute([$rid,$bm['user_id'],date('Y-m-01'),date('Y-m-d')]);$paid=(float)$q->fetchColumn();$members[]=['user_id'=>$bm['user_id'],'name'=>$bm['name'],'meals'=>max(0,$days*$sessions-$off),'paid'=>$paid];}
$x=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE room_id=? AND expense_date BETWEEN ? AND ?");$x->execute([$rid,date('Y-m-01'),date('Y-m-d')]);$expense=(float)$x->fetchColumn();$totalMeals=0;foreach($members as $mm){$q=db()->prepare("SELECT COUNT(*) FROM meals WHERE room_id=? AND user_id=? AND meal_date BETWEEN ? AND ? AND status='off'");$q->execute([$rid,$mm['user_id'],date('Y-m-01'),date('Y-m-d')]);$offm=(int)$q->fetchColumn();$totalMeals+=max(0,$days*$sessions-$offm);}$rate=$totalMeals?($expense/$totalMeals):0;$title='Money & balances';include 'includes/header.php';?><div class="d-flex justify-content-between mb-4"><div><h2 class="fw-bold">Monthly money</h2><p class="small-muted"><?=e($month)?> · Expense <?=money($expense)?> · Meal rate <?=money($rate)?></p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Member</th><th>Meals</th><th>Meal cost</th><th>Paid</th><th>Balance</th><?php if(room_role()==='manager'):?><th>Record payment</th><?php endif;?></tr></thead><tbody><?php foreach($members as $m):$cost=$m['meals']*$rate;$bal=(float)$m['paid']-$cost;?><tr><td><b><?=e($m['name'])?></b></td><td><?=$m['meals']?></td><td><?=money($cost)?></td><td><?=money((float)$m['paid'])?></td><td class="<?=$bal<0?'text-danger':'text-success'?>"><b><?=money($bal)?></b></td><?php if(room_role()==='manager'):?><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><input class="form-control form-control-sm" style="width:100px" name="amount" type="number" step=".01" placeholder="৳"><select class="form-select form-select-sm" name="method" style="width:95px"><option>Cash</option><option>bKash</option><option>Nagad</option><option>Bank</option></select><button class="btn btn-sm btn-dark">Add</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div><?php include 'includes/footer.php';?>